    if code == pend['otp']:
        _pending_2fa.pop(ip, None)
        _clear_auth_lockout(ip)
        session.permanent = True
        session['authenticated'] = True
        session['admin_user'] = pend['username']
        session['role'] = 'admin'
        session.pop('operator_id', None)
        session.pop('operator_token', None)
